create table property
(
    id            int unsigned auto_increment
        primary key,
    pricePerWeek  double           null,
    addressLine1  varchar(60)      null,
    addressLine2  varchar(27)      null,
    bedroomCount  double           null,
    bathroomCount double           null,
    parkingCount  double           null,
    propertyType  tinyint unsigned null,
    houseId       int              null,
    commuteTime   double           null,
    availableDate datetime         null,
    keywords      text             null,
    averageScore  double           null,
    description   varchar(1024)    null,
    descriptionCN varchar(1024)    null,
    url           varchar(255)     null,
    publishedAt   datetime         null
)
    collate = utf8mb4_unicode_ci;

create index property_availableDate_idx
    on property (availableDate);

create index property_averageScore_idx
    on property (averageScore);

create index property_bathroomCount_idx
    on property (bathroomCount);

create index property_bedroomCount_idx
    on property (bedroomCount);

create index property_commuteTime_idx
    on property (commuteTime);

create index property_pricePerWeek_idx
    on property (pricePerWeek);

create index property_propertyType_idx
    on property (propertyType);

create index property_publishedAt_idx
    on property (publishedAt);


